const $=s=>document.querySelector(s),svg=$('#canvas'),NS='http://www.w3.org/2000/svg';
const examples=[['Unknot',1,'Unknot · 0₁'],['Unlink',0,'Two-component unlink'],['Hopf link',2,'Positive Hopf link'],['Trefoil',3,'Trefoil · 3₁'],['4-crossing link',4,'Torus link · T(2,4)'],['Cinquefoil',5,'Cinquefoil · 5₁']];
let paths=[],choices={},hits=[],comps=[],mode='explore',draft=[],selected=0,current=3,modified=false,history=[],result;
function element(tag,attrs,parent=svg){let el=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));parent.append(el);return el;}
function line(points,attrs={}){return element('path',{d:points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' '),fill:'none',stroke:'#000','stroke-width':5,'stroke-linecap':'round','stroke-linejoin':'round',...attrs});}
function circlePath(cx,cy,r){let ps=[];for(let i=0;i<=65;i++){let t=i/65*Math.PI*2;ps.push([cx+r*Math.cos(t),cy+r*Math.sin(t)]);}return ps;}
function trefoilPath(){
 const anchors=[[255,85],[310,84],[355,104],[380,145],[375,190],[340,230],[290,262],[240,285],[207,315],[201,365],[220,422],[258,480],[300,518],[355,538],[410,539],[470,504],[515,455],[549,385],[565,310],[573,240],[566,185],[550,131],[516,78],[482,48],[425,30],[380,29],[335,40],[299,50],[267,75],[248,112],[245,155],[263,210],[287,265],[310,325],[323,381],[322,425],[311,470],[282,506],[235,530],[180,533],[157,523],[134,498],[108,472],[91,432],[80,382],[76,324],[76,272],[80,222],[92,179],[113,143],[151,112],[190,95],[225,87]];
 const p=[],n=anchors.length;
 for(let i=0;i<n;i++){const a=anchors[(i+n-1)%n],b=anchors[i],c=anchors[(i+1)%n],d=anchors[(i+2)%n];for(let j=0;j<16;j++){const t=j/16,t2=t*t,t3=t2*t;let xy=[0,1].map(k=>.5*(2*b[k]+(-a[k]+c[k])*t+(2*a[k]-5*b[k]+4*c[k]-d[k])*t2+(-a[k]+3*b[k]-3*c[k]+d[k])*t3));p.push([290+.9*(xy[0]-324),290+.9*(xy[1]-284)]);}}
 p.push(p[0]);return p;
}
function preset(n){if(n===3)return [trefoilPath()];if(n===0)return [circlePath(220,235,72),circlePath(375,235,72)];let x=[215,365],top=84,bottom=386,tracks=[[],[]];for(let s=0;s<2;s++){for(let k=0;k<=n;k++)tracks[s].push([x[(s+k)%2],top+(bottom-top)*k/n]);}
 let visited=new Set(),out=[];for(let s=0;s<2;s++){if(visited.has(s))continue;let start=s,now=s,p=[];do{visited.add(now);let tr=tracks[now];p.push(...(p.length?tr.slice(1):tr));let end=(now+n)%2,outer=end===0?119:461;p.push([outer,bottom+22],[outer,top-22],[x[end],top]);now=end;}while(now!==start);out.push(p);}return out;
}
function snapshot(){history.push(JSON.stringify({paths,choices,draft,modified,current}));if(history.length>40)history.shift();}
function load(idx){current=idx;modified=false;draft=[];choices={};paths=preset(examples[idx][1]);let initial=Skein.intersections(paths);initial.hits.forEach(h=>{choices[h.key]=h.sign===(idx===3?-1:1)?h.over:!h.over;});history=[];selected=0;setMode('explore');render();calculate();}
function setMode(m){mode=m;$('#explore').classList.toggle('active',m==='explore');$('#draw').classList.toggle('active',m==='draw');$('#hint').textContent=m==='draw'?'Drag to draw; release to close the loop.':'Click a crossing to switch it.';}
function render(){svg.replaceChildren();let data=Skein.intersections(paths,choices);hits=data.hits;comps=data.comps;let pieces=strandPieces(paths,hits);pieces.forEach(p=>line(p,{'stroke-width':10}));pieces.forEach(p=>line(p,{stroke:'#fff','stroke-width':4}));
 hits.forEach(h=>{if(selected===h.id)element('circle',{cx:h.x,cy:h.y,r:24,fill:'#ddd',opacity:.45,stroke:'#000','stroke-dasharray':'3 4'});element('text',{x:h.x+17,y:h.y-13,fill:'#000','font-size':11,'font-family':'DM Sans, sans-serif'},svg).textContent=h.id;let target=element('circle',{cx:h.x,cy:h.y,r:18,fill:'transparent',cursor:'pointer','aria-label':'Switch crossing '+h.id,tabindex:0,role:'button'});let toggle=()=>{snapshot();choices[h.key]=!h.over;modified=true;selected=h.id;render();calculate();};target.addEventListener('click',e=>{e.stopPropagation();toggle();});target.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle();}});});
 // Arrows on the first non-crossing segment show the traversal orientation.
 paths.forEach((p,i)=>{if(p.length<2)return;let a=p[0],b=p[1],u=[b[0]-a[0],b[1]-a[1]],l=Math.hypot(...u),m=[a[0]+u[0]*.23,a[1]+u[1]*.23],d=[u[0]/l,u[1]/l];line([[m[0]-7*d[0]+4*d[1],m[1]-7*d[1]-4*d[0]],m,[m[0]-7*d[0]-4*d[1],m[1]-7*d[1]+4*d[0]]],{stroke:'#000','stroke-width':3});});
 if(draft.length){line(draft,{'stroke-width':10});line(draft,{stroke:'#fff','stroke-width':4});}
 $('#badge').textContent=hits.length+' crossings · '+paths.length+' component'+(paths.length!==1?'s':'');$('#knotname').textContent=modified?'Your edited diagram':examples[current][2];$('#presets').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',!modified&&i===current));$('#undo').disabled=!history.length;
}
function depth(n){return n.base?0:1+Math.max(depth(n.switched),depth(n.smoothed));}
function local(kind,sign){let diagA='M14 10L44 48',diagB='M44 10L14 48',over=(sign===1?diagB:diagA);return '<svg viewBox="0 0 58 58" aria-label="'+kind+' local diagram"><defs><marker id="arr'+kind+sign+'" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#000"/></marker></defs>'+(kind==='Smooth'?'<path d="M14 10Q29 29 14 48M44 10Q29 29 44 48" fill="none" stroke="#000" stroke-width="2.5"/>':'<path d="'+diagA+' '+diagB+'" stroke="#000" stroke-width="2.5"/><path d="'+over+'" stroke="#fff" stroke-width="9"/><path d="'+over+'" stroke="#000" stroke-width="2.5"/>')+'<path d="M14 10l3 4M44 10l-3 4" stroke="#000" stroke-width="2" marker-end="url(#arr'+kind+sign+')"/></svg>';}
function miniDiagram(n){
 let d='<svg class="mini" viewBox="0 0 580 580" role="img" aria-label="Intermediate link diagram, '+n.crossings+' crossings">';
 const path=(a,stroke,width=5)=>'<path d="'+a+'" fill="none" stroke="'+stroke+'" stroke-width="'+width+'" stroke-linecap="round" stroke-linejoin="round"/>';
 const pieces=strandPieces(paths,hits,n.signs),pd=p=>p.map((v,i)=>(i?'L':'M')+v.join(',')).join(' ');pieces.forEach(p=>d+=path(pd(p),'#000',10));pieces.forEach(p=>d+=path(pd(p),'#fff',4));
 hits.forEach(h=>{const unit=v=>{let l=Math.hypot(...v);return v.map(x=>x/l);},u=unit(h.u),v=unit(h.v),pos=(v,k)=>[h.x+k*v[0],h.y+k*v[1]].join(',');
 if(n.signs[h.id]===undefined){d+='<circle cx="'+h.x+'" cy="'+h.y+'" r="15" fill="#fff"/>';let a='M'+pos(u,-15)+'Q'+h.x+','+h.y+' '+pos(v,15),b='M'+pos(v,-15)+'Q'+h.x+','+h.y+' '+pos(u,15);d+=path(a,'#000',10)+path(b,'#000',10)+path(a,'#fff',4)+path(b,'#fff',4);}

 if(n.crossing===h.id)d+='<circle cx="'+h.x+'" cy="'+h.y+'" r="25" fill="#ddd" opacity=".5" stroke="#000" stroke-dasharray="4 4"/>';
 });return d+'</svg>';
}
let renderedNodes=0;
function nodeHTML(n,level=0,label='diagram'){if(++renderedNodes>500)return '<div class="base">Further branches omitted from display; included in the exact calculation.</div>';if(n.base)return '<div class="base"><span>○ '+n.reason+'</span><b class="math">'+Skein.format(n.poly)+'</b></div>';
 return '<details class="node" '+(level<1?'open':'')+'><summary><b>'+label+'</b><small>'+n.crossings+' crossings · '+n.components+' component'+(n.components===1?'':'s')+'</small><span class="math">'+Skein.format(n.poly)+'</span></summary><div class="branch"><div class="nodevisual">'+miniDiagram(n)+'<p>The diagram at this state. The marked crossing is switched and smoothed below. Reconnecting arcs show earlier smoothings.</p></div><div class="local"><div>'+local('Original',n.sign)+'Original '+(n.sign>0?'+':'−')+'</div><span>→</span><div>'+local('Switch',-n.sign)+'Switch</div><span>'+(n.sign>0?'+':'−')+' z ×</span><div>'+local('Smooth',n.sign)+'Smooth</div><button class="locate" data-crossing="'+n.crossing+'">Locate crossing '+n.crossing+'</button></div><div class="equation">∇ = ('+Skein.format(n.switched.poly)+') '+(n.sign>0?'+':'−')+' z ('+Skein.format(n.smoothed.poly)+') = '+Skein.format(n.poly)+'</div><p class="branchlabel">◉ Switch crossing '+n.crossing+(n.cached?' · reused state':'')+'</p>'+nodeHTML(n.switched,level+1,'switched')+'<p class="branchlabel">⌁ Smooth crossing '+n.crossing+'</p>'+nodeHTML(n.smoothed,level+1,'smoothed')+'</div></details>';
}
function calculate(){if(!paths.length){$('#status').textContent='Close your drawing to calculate its polynomial.';return;}if(draft.length){$('#status').textContent='Release to close the loop.';return;}try{if(hits.length>12)throw Error('Please use 12 crossings or fewer for interactive recursion.');result=Skein.solve(comps);$('#alex').textContent='Alexander polynomial: '+coefficientList(result.poly);showMatches(result.poly);$('#conway').innerHTML='∇(z) = '+Skein.format(result.poly);$('#states').textContent=result.states;$('#depth').textContent=depth(result.tree);$('#components').textContent=paths.length;renderedNodes=0;$('#tree').innerHTML=nodeHTML(result.tree);$('#status').textContent=paths.length>1?'Arrows show component orientations.':'';$('#tree').querySelectorAll('[data-crossing]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.crossing);render();svg.scrollIntoView({behavior:'smooth',block:'center'});});}catch(e){$('#atlas-gallery').replaceChildren();$('#match-note').textContent='';$('#status').textContent=e.message;$('#alex').textContent='Calculation unavailable';$('#conway').textContent='—';$('#states').textContent='—';$('#depth').textContent='—';$('#tree').replaceChildren();}}
examples.forEach((e,i)=>{let b=document.createElement('button');b.textContent=e[0];b.onclick=()=>load(i);$('#presets').append(b);});
$('#draw').onclick=()=>{if(mode==='draw')return;$('#clear').onclick();};
$('#explore').onclick=()=>{if(draft.length){$('#status').textContent='Finish drawing, or choose an example.';return;}setMode('explore');};
let drawing=false;
function canvasPoint(e){let box=svg.getBoundingClientRect();return [(e.clientX-box.left)*580/box.width,(e.clientY-box.top)*580/box.height];}
function simplify(ps,tol=.65){if(ps.length<3)return ps;let a=ps[0],b=ps.at(-1),dx=b[0]-a[0],dy=b[1]-a[1],l=dx*dx+dy*dy,max=0,idx=0;for(let i=1;i<ps.length-1;i++){let t=l?Math.max(0,Math.min(1,((ps[i][0]-a[0])*dx+(ps[i][1]-a[1])*dy)/l)):0,d=Math.hypot(ps[i][0]-a[0]-t*dx,ps[i][1]-a[1]-t*dy);if(d>max){max=d;idx=i;}}return max>tol?[...simplify(ps.slice(0,idx+1),tol).slice(0,-1),...simplify(ps.slice(idx),tol)]:[a,b];}
function closeDrawing(){if(draft.length<3)return;draft=simplify(draft);if(draft.length<3)return;paths=[[...draft,draft[0]]];draft=[];modified=true;setMode('explore');render();calculate();}
svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;if(mode!=='draw'){if(e.target.hasAttribute('aria-label')&&e.target.getAttribute('aria-label').startsWith('Switch crossing'))return;$('#draw').onclick();}e.preventDefault();snapshot();drawing=true;svg.setPointerCapture(e.pointerId);draft.push(canvasPoint(e));render();});
svg.addEventListener('pointermove',e=>{if(!drawing)return;let p=canvasPoint(e);if(Math.hypot(p[0]-draft.at(-1)[0],p[1]-draft.at(-1)[1])>=2){draft.push(p);render();}});
function finishStroke(e){if(!drawing)return;drawing=false;let p=canvasPoint(e);if(Math.hypot(p[0]-draft.at(-1)[0],p[1]-draft.at(-1)[1])>1)draft.push(p);draft=simplify(draft);if(draft.length>2&&Math.hypot(draft.at(-1)[0]-draft[0][0],draft.at(-1)[1]-draft[0][1])<.1)draft.pop();if(draft.length>=3){closeDrawing();}else{draft=[];render();$('#status').textContent='Draw a curve with a little more shape.';}}
svg.addEventListener('pointerup',finishStroke);svg.addEventListener('pointercancel',()=>{drawing=false;render();});
$('#clear').onclick=()=>{snapshot();paths=[];choices={};draft=[];modified=true;selected=0;setMode('draw');render();$('#alex').textContent='Alexander polynomial:';$('#conway').textContent='';$('#tree').replaceChildren();$('#atlas-gallery').replaceChildren();$('#match-note').textContent='';$('#status').textContent='';};
$('#undo').onclick=()=>{if(!history.length)return;let state=JSON.parse(history.pop());({paths,choices,draft,modified,current}=state);setMode(draft.length||!paths.length?'draw':'explore');render();if(paths.length&&!draft.length)calculate();else{$('#alex').textContent='Draw your knot';$('#conway').textContent='—';$('#tree').innerHTML='<div class="base">Finish your drawing to calculate.</div>';}};
$('#calculate').onclick=()=>{calculate();$('.recursion').hidden=false;$('#tree').scrollIntoView({behavior:'smooth',block:'center'});};$('#expand').onclick=()=>$('#tree').querySelectorAll('details').forEach(d=>d.open=true);$('#collapse').onclick=()=>$('#tree').querySelectorAll('details').forEach(d=>d.open=false);$('#help').onclick=()=>$('#guide').scrollIntoView({behavior:'smooth'});


const atlasImages={'3_1':'https://katlas.org/images/c/cb/3_1.gif','4_1':'https://katlas.org/images/6/6a/4_1.gif','5_1':'https://katlas.org/images/2/27/5_1.gif','10_1':'https://katlas.org/images/1/13/10_1.gif','10_132':'https://katlas.org/images/c/cd/10_132.gif','6_1':'https://katlas.org/images/2/22/6_1.gif','9_46':'https://katlas.org/images/8/8a/9_46.gif'};
const atlasMatches={'1,0,1':['3_1'],'1,0,-1':['4_1'],'1,0,3,0,1':['5_1','10_132'],'1,0,-2':['6_1','9_46'],'1,0,-4':['10_1']};
function coefficientList(poly){let p=Skein.alexander(poly);if(!p.length)return '0';let m=new Map(p),hi=p[0][0],lo=p.at(-1)[0],out=[];for(let i=hi;i>=lo;i-=2)out.push(m.get(i)||0);if(hi%2)return Skein.formatAlexander(poly).replace(/<sup>(.*?)<\/sup>/g,'^($1)');if(out[0]<0)out=out.map(x=>-x);return out.join(',');}
function atlasGallery(ids,reference=false){$('#atlas-gallery').replaceChildren();ids.forEach((id,i)=>{if(i){let or=document.createElement('span');or.textContent='or';$('#atlas-gallery').append(or);}let box=document.createElement('div'),link=document.createElement('a'),img=document.createElement('img'),caption=document.createElement('a');link.href='https://katlas.org/wiki/'+id;link.target='_blank';link.rel='noreferrer';img.src=atlasUrls[id]||atlasImages[id];img.alt='Knot Atlas '+id;img.width=300;img.height=320;img.onerror=()=>{img.alt='View '+id+' at Knot Atlas';};link.append(img);caption.href=link.href;caption.target='_blank';caption.rel='noreferrer';caption.textContent=id;box.append(link,caption);$('#atlas-gallery').append(box);});$('#match-note').textContent=reference?'reference images':ids.length?'possible polynomial matches':'No prime-knot match through 10 crossings.';}
function showMatches(poly){atlasGallery(atlasIndex[coefficientList(poly)]||[]);}
$('#atlas-select').onchange=()=>{let k=$('#atlas-select').value;atlasGallery(k==='5_1'?['5_1','10_132']:k==='6_1'?['6_1','9_46']:[k],true);};
$('#browse').onclick=()=>{$('#atlas-browser').hidden=!$('#atlas-browser').hidden;};
